package com.lims.dao;

import com.lims.model.Stocktake;
import com.lims.model.StocktakeDetail;
import com.lims.model.User;
import com.lims.util.DBContext;
import java.sql.*;
import java.util.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class StocktakeDAO {
    private static final Logger LOG=Logger.getLogger(StocktakeDAO.class.getName());
    public List<User> warehouseStaff(){
        List<User> out=new ArrayList<>(); String q="SELECT DISTINCT u.UserID,u.Username,u.FullName,u.Email,u.Phone,u.Status,u.CreatedAt FROM USERS u JOIN USER_ROLES ur ON ur.UserID=u.UserID JOIN ROLES r ON r.RoleID=ur.RoleID WHERE u.Status='ACTIVE' AND LOWER(r.RoleName)=LOWER('Warehouse Staff') ORDER BY u.FullName";
        try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())out.add(new User(r.getInt("UserID"),r.getString("Username"),null,r.getString("FullName"),r.getString("Email"),r.getString("Phone"),r.getString("Status"),r.getTimestamp("CreatedAt")));}catch(SQLException e){LOG.log(Level.SEVERE,"warehouse staff",e);}return out;
    }
    public int create(int manager,int staff,String location,String note){
        String q="INSERT INTO INVENTORY_CHECKS(CreatedBy,AssignedTo,LocationFilter,Note,Status) OUTPUT INSERTED.CheckID VALUES(?,?,?,?, 'ASSIGNED')";
        try(Connection c=DBContext.getConnection()){c.setAutoCommit(false);int id;
            try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,manager);p.setInt(2,staff);p.setString(3,emptyNull(location));p.setString(4,emptyNull(note));try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("No check id");id=r.getInt(1);}}
            String snap="INSERT INTO INVENTORY_CHECK_DETAILS(CheckID,InventoryID,ProductID,SerialNumber,SystemStatus,SystemLocation) SELECT ?,i.InventoryID,i.ProductID,i.SerialNumber,i.Status,i.Location FROM INVENTORY i WHERE i.Status<>'EXPORTED' AND (? IS NULL OR i.Location LIKE ?+'%')";
            try(PreparedStatement p=c.prepareStatement(snap)){p.setInt(1,id);String f=emptyNull(location);p.setString(2,f);p.setString(3,f);p.executeUpdate();} c.commit();return id;
        }catch(SQLException e){LOG.log(Level.SEVERE,"create stocktake",e);return -1;}
    }
    public List<Stocktake> managerList(String status){List<Stocktake> rows=list("",0,status);for(Stocktake s:rows){Stocktake full=find(s.getCheckId());if(full!=null)s.setDetails(full.getDetails());}return rows;}
    public List<Stocktake> assignedList(int staff){return list(" AND ic.AssignedTo=?",staff,"ALL");}
    private List<Stocktake> list(String extra,int user,String status){List<Stocktake> out=new ArrayList<>();String q="SELECT ic.*,u.FullName StaffName,m.FullName ManagerName FROM INVENTORY_CHECKS ic JOIN USERS u ON u.UserID=ic.AssignedTo JOIN USERS m ON m.UserID=ic.CreatedBy WHERE (?='ALL' OR ic.Status=?)"+extra+" ORDER BY CASE WHEN ic.Status IN ('PENDING_MANAGER','ASSIGNED','REJECTED') THEN 0 ELSE 1 END,ic.CheckDate DESC";
        try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setString(1,status);p.setString(2,status);if(user>0)p.setInt(3,user);try(ResultSet r=p.executeQuery()){while(r.next())out.add(mapCheck(r));}}catch(SQLException e){LOG.log(Level.SEVERE,"list stocktakes",e);}return out;}
    public Stocktake find(int id){String q="SELECT ic.*,u.FullName StaffName,m.FullName ManagerName FROM INVENTORY_CHECKS ic JOIN USERS u ON u.UserID=ic.AssignedTo JOIN USERS m ON m.UserID=ic.CreatedBy WHERE ic.CheckID=?";try(Connection c=DBContext.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next()){Stocktake s=mapCheck(r);s.setDetails(details(c,id));return s;}}}catch(SQLException e){LOG.log(Level.SEVERE,"find stocktake",e);}return null;}
    public boolean submit(int id,int staff,List<StocktakeDetail> details){try(Connection c=DBContext.getConnection()){c.setAutoCommit(false);try(PreparedStatement lock=c.prepareStatement("SELECT Status FROM INVENTORY_CHECKS WITH(UPDLOCK) WHERE CheckID=? AND AssignedTo=?")){lock.setInt(1,id);lock.setInt(2,staff);try(ResultSet r=lock.executeQuery()){if(!r.next()||!(r.getString(1).equals("ASSIGNED")||r.getString(1).equals("REJECTED")))return rollback(c);}}
        Set<Integer> submitted=new HashSet<>();for(StocktakeDetail d:details){if(d.getDetailId()>0){submitted.add(d.getDetailId());String q="UPDATE INVENTORY_CHECK_DETAILS SET IsCounted=1,ActualStatus=?,ActualLocation=?,DiscrepancyReason=? WHERE CheckID=? AND CheckDetailID=?";try(PreparedStatement p=c.prepareStatement(q)){p.setString(1,d.getActualStatus());p.setString(2,emptyNull(d.getActualLocation()));p.setString(3,emptyNull(d.getDiscrepancyReason()));p.setInt(4,id);p.setInt(5,d.getDetailId());if(p.executeUpdate()!=1)return rollback(c);}}else{String q="INSERT INTO INVENTORY_CHECK_DETAILS(CheckID,ProductID,SerialNumber,ActualStatus,ActualLocation,IsCounted,DiscrepancyReason) VALUES(?,?,?,?,?,1,?)";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);p.setInt(2,d.getProductId());p.setString(3,d.getSerialNumber());p.setString(4,d.getActualStatus());p.setString(5,d.getActualLocation());p.setString(6,emptyNull(d.getDiscrepancyReason()));p.executeUpdate();}}}
        try(PreparedStatement p=c.prepareStatement("SELECT CheckDetailID FROM INVENTORY_CHECK_DETAILS WHERE CheckID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next())if(!submitted.contains(r.getInt(1))){ // New rows were not in the initial submitted set; counted below.
                    try(PreparedStatement v=c.prepareStatement("SELECT IsCounted FROM INVENTORY_CHECK_DETAILS WHERE CheckDetailID=?")){v.setInt(1,r.getInt(1));try(ResultSet vr=v.executeQuery()){if(vr.next()&&!vr.getBoolean(1))return rollback(c);}}
                }}}
        try(PreparedStatement p=c.prepareStatement("UPDATE INVENTORY_CHECKS SET Status='PENDING_MANAGER',CancelReason=NULL WHERE CheckID=? AND AssignedTo=?")){p.setInt(1,id);p.setInt(2,staff);if(p.executeUpdate()!=1)return rollback(c);}c.commit();return true;
    }catch(SQLException e){LOG.log(Level.SEVERE,"submit stocktake",e);return false;}}
    public boolean decide(int id,int manager,boolean approve,String reason){try(Connection c=DBContext.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("SELECT Status FROM INVENTORY_CHECKS WITH(UPDLOCK) WHERE CheckID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()||!"PENDING_MANAGER".equals(r.getString(1)))return rollback(c);}}
        if(approve){List<StocktakeDetail> rows=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT InventoryID,ProductID,SerialNumber,SystemStatus,ActualStatus,SystemLocation,ActualLocation,IsCounted FROM INVENTORY_CHECK_DETAILS WITH(UPDLOCK) WHERE CheckID=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){StocktakeDetail d=new StocktakeDetail();d.setInventoryId(r.getInt("InventoryID"));if(r.wasNull())d.setInventoryId(0);d.setProductId(r.getInt("ProductID"));d.setSerialNumber(r.getString("SerialNumber"));d.setSystemStatus(r.getString("SystemStatus"));d.setActualStatus(r.getString("ActualStatus"));d.setSystemLocation(r.getString("SystemLocation"));d.setActualLocation(r.getString("ActualLocation"));d.setCounted(r.getBoolean("IsCounted"));rows.add(d);}}}
            for(StocktakeDetail d:rows){if(!d.isCounted()||d.getActualStatus()==null)return rollback(c);if(d.getInventoryId()>0){try(PreparedStatement check=c.prepareStatement("SELECT Status,Location FROM INVENTORY WITH(UPDLOCK) WHERE InventoryID=?")){check.setInt(1,d.getInventoryId());try(ResultSet cr=check.executeQuery()){if(!cr.next()||!Objects.equals(cr.getString(1),d.getSystemStatus())||!Objects.equals(cr.getString(2),d.getSystemLocation()))return rollback(c);}}try(PreparedStatement u=c.prepareStatement("UPDATE INVENTORY SET Status=?,Location=?,UpdatedAt=GETDATE() WHERE InventoryID=?")){u.setString(1,d.getActualStatus());u.setString(2,"MISSING".equals(d.getActualStatus())?d.getSystemLocation():d.getActualLocation());u.setInt(3,d.getInventoryId());u.executeUpdate();}}else{try(PreparedStatement ins=c.prepareStatement("INSERT INTO INVENTORY(ProductID,SerialNumber,Location,Status) VALUES(?,?,?,?)")){ins.setInt(1,d.getProductId());ins.setString(2,d.getSerialNumber());ins.setString(3,d.getActualLocation());ins.setString(4,d.getActualStatus());ins.executeUpdate();}}}}
        String q="UPDATE INVENTORY_CHECKS SET Status=?,ApprovedBy=?,ApprovedDate=GETDATE(),CancelReason=? WHERE CheckID=?";try(PreparedStatement p=c.prepareStatement(q)){p.setString(1,approve?"APPROVED":"REJECTED");p.setInt(2,manager);p.setString(3,approve?null:reason);p.setInt(4,id);p.executeUpdate();}c.commit();return true;
    }catch(SQLException e){LOG.log(Level.SEVERE,"decide stocktake",e);return false;}}
    private List<StocktakeDetail> details(Connection c,int id)throws SQLException{List<StocktakeDetail> out=new ArrayList<>();String q="SELECT d.*,p.ProductCode,p.ProductName FROM INVENTORY_CHECK_DETAILS d JOIN PRODUCTS p ON p.ProductID=d.ProductID WHERE d.CheckID=? ORDER BY d.CheckDetailID";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){StocktakeDetail d=new StocktakeDetail();d.setDetailId(r.getInt("CheckDetailID"));d.setInventoryId(r.getInt("InventoryID"));d.setProductId(r.getInt("ProductID"));d.setProductCode(r.getString("ProductCode"));d.setProductName(r.getString("ProductName"));d.setSerialNumber(r.getString("SerialNumber"));d.setSystemStatus(r.getString("SystemStatus"));d.setActualStatus(r.getString("ActualStatus"));d.setSystemLocation(r.getString("SystemLocation"));d.setActualLocation(r.getString("ActualLocation"));d.setCounted(r.getBoolean("IsCounted"));d.setDiscrepancyReason(r.getString("DiscrepancyReason"));out.add(d);}}}return out;}
    private Stocktake mapCheck(ResultSet r)throws SQLException{Stocktake s=new Stocktake();s.setCheckId(r.getInt("CheckID"));s.setAssignedTo(r.getInt("AssignedTo"));s.setStatus(r.getString("Status"));s.setNote(r.getString("Note"));s.setLocationFilter(r.getString("LocationFilter"));s.setCancelReason(r.getString("CancelReason"));s.setStaffName(r.getString("StaffName"));s.setManagerName(r.getString("ManagerName"));s.setCheckDate(r.getTimestamp("CheckDate"));s.setApprovedDate(r.getTimestamp("ApprovedDate"));return s;}
    private static String emptyNull(String s){return s==null||s.trim().isEmpty()?null:s.trim();}
    private boolean rollback(Connection c){try{c.rollback();}catch(SQLException ignored){}return false;}
}
